#!/usr/bin/env python3
"""Week 4 · harness for Task 3. Do not edit this file.

A slotted simulation of one bottleneck link, so that everybody's congestion
control is judged on the same network instead of on their own Wi-Fi.

    link       1 packet per slot, propagation RTT of 20 slots
    queue      10 packets, tail drop
    run        4000 slots

Four numbers come back:

    goodput      packets delivered once, per 1000 slots   (higher is better)
    loss         fraction of transmissions that were dropped
    retx         retransmissions
    avg queue    mean queue occupancy - how much delay you inflicted on others

    python3 bench.py
    python3 bench.py --yours
"""
import argparse

CAPACITY = 1          # packets drained per slot
RTT = 20              # slots, one way is RTT/2
QUEUE = 10            # tail-drop queue depth
SLOTS = 4000
TIMEOUT = 3 * RTT     # slots before a sender gives up on an unacked packet


def simulate(control_cls):
    """One sender, one bottleneck link, tail-drop queue.

    The sender sees exactly what a real one sees: ACKs that come back, and
    packets that never do. A packet pushed into a full queue is *silently*
    dropped - the sender finds out only when the timeout fires.
    """
    cc = control_cls()
    queue = []            # seqs waiting for the link
    inflight = {}         # seq -> slot it was (re)sent
    ack_events = []       # (slot the ACK lands, seq)
    resend = []           # seqs that timed out and must go again
    delivered = set()
    sent = dropped = retx = queue_sum = 0
    next_seq = 0

    for slot in range(SLOTS):
        # --- ACKs landing now
        due = [s for t, s in ack_events if t == slot]
        ack_events = [(t, s) for t, s in ack_events if t > slot]
        for seq in due:
            if seq in inflight:
                del inflight[seq]
                delivered.add(seq)
                cc.on_ack()

        # --- timeouts: the only way a loss becomes visible
        for seq in [s for s, t in inflight.items() if slot - t >= TIMEOUT]:
            del inflight[seq]
            resend.append(seq)
            cc.on_loss()

        # --- send while the window allows
        window = max(1, int(cc.window))
        while len(inflight) < window:
            if resend:
                seq, again = resend.pop(0), True
            else:
                seq, again = next_seq, False
                next_seq += 1
            sent += 1
            retx += again
            inflight[seq] = slot
            if len(queue) >= QUEUE:
                dropped += 1          # tail drop, and nobody tells the sender
            else:
                queue.append(seq)

        # --- the link drains
        for _ in range(CAPACITY):
            if queue:
                ack_events.append((slot + RTT, queue.pop(0)))
        queue_sum += len(queue)

    return {
        "goodput": len(delivered) / SLOTS * 1000,
        "loss": dropped / max(sent, 1),
        "retx": retx,
        "queue": queue_sum / SLOTS,
    }


def show(label, r):
    print(f"  {label:<10} goodput {r['goodput']:>6.1f}/1000 slots   "
          f"loss {r['loss']:>6.1%}   retx {r['retx']:>5}   "
          f"avg queue {r['queue']:>5.1f}")


def main():
    p = argparse.ArgumentParser()
    p.add_argument("--yours", action="store_true")
    a = p.parse_args()

    from task3_congestion import FixedWindow
    print(f"\n  link 1 pkt/slot, RTT {RTT} slots, queue {QUEUE}, {SLOTS} slots\n")
    base = simulate(FixedWindow)
    show("baseline", base)

    if a.yours:
        from task3_congestion import YourControl
        mine = simulate(YourControl)
        show("yours", mine)
        print()
        ok_loss = mine["loss"] <= 0.05
        ok_queue = mine["queue"] <= 5.0
        share = mine["goodput"] / base["goodput"]
        for label, ok in [("loss at most 5%", ok_loss),
                          ("average queue at most 5.0", ok_queue)]:
            print(f"   {'ok  ' if ok else 'FAIL'}  {label}")
        print(f"   goodput {share:.0%} of the baseline")
        if not (ok_loss and ok_queue):
            grade = "not yet"
        elif share >= 0.93:
            grade = "strong"
        elif share >= 0.85:
            grade = "good"
        else:
            grade = "pass"
        print(f"\n   -> {grade}")
        if grade != "not yet":
            print("\n  Note that the baseline still has the highest goodput here.")
            print("  observation.md: why is it the worst sender anyway?")
    print()


if __name__ == "__main__":
    main()
